ALTER POLICY "Authenticated users can upload forum images" ON storage.objects TO authenticated WITH CHECK (bucket_id='forum-images' AND owner_id = auth.uid()::text AND (storage.foldername(name))[1] = auth.uid()::text);
ALTER POLICY "Authenticated can list forum images" ON storage.objects USING (bucket_id='forum-images' AND (owner_id = auth.uid()::text OR public.has_role(auth.uid(),'super_admin'::public.app_role)));
ALTER POLICY "Anyone can view post categories" ON public.post_categories USING (EXISTS (SELECT 1 FROM public.posts p WHERE p.id = post_categories.post_id AND (p.status='published'::public.post_status OR p.author_id = auth.uid() OR public.has_role(auth.uid(),'super_admin'::public.app_role))));
ALTER POLICY "Anyone can view post tags" ON public.post_tags USING (EXISTS (SELECT 1 FROM public.posts p WHERE p.id = post_tags.post_id AND (p.status='published'::public.post_status OR p.author_id = auth.uid() OR public.has_role(auth.uid(),'super_admin'::public.app_role))));